import{_ as s,C as n,c as r,o as l,a3 as o,G as a}from"./chunks/framework.Dokpd4od.js";const b=JSON.parse('{"title":"Mark an opportunity won or lost","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/crm/pipeline/mark-won-lost.md","filePath":"master/sales/crm/pipeline/mark-won-lost.md","lastUpdated":1793789158000}'),i={name:"master/sales/crm/pipeline/mark-won-lost.md"};function d(p,t,h,g,c,u){const e=n("ImagePopup");return l(),r("div",null,[t[0]||(t[0]=o('<h1 id="mark-an-opportunity-won-or-lost" tabindex="-1">Mark an opportunity won or lost <a class="header-anchor" href="#mark-an-opportunity-won-or-lost" aria-label="Permalink to &quot;Mark an opportunity won or lost&quot;">​</a></h1><p>When a deal ends, you close it. A won deal moves to the won stage. A lost deal keeps a reason and a note, so you can learn why customers say no.</p><blockquote><p><strong>In simple words:</strong> Click <strong>Won</strong> when the customer says yes. Click <strong>Lost</strong> when they say no, and say why.</p></blockquote><p>You can close a deal from the opportunity page, from a list row menu, or from the Teams pipeline. The steps are the same everywhere.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>To mark a deal won, one stage must be a won stage. Go to <code>CRM → Configuration → Stages</code>, open the stage and turn on <strong>Is Won Stage?</strong>. See <a href="./../configuration/stages.html">Stages</a>.</p><p>Without a won stage, clicking <strong>Won</strong> shows the warning <strong>No won stage</strong>. It tells you to set one first.</p><p>For lost deals, prepare your reasons in <code>CRM → Configuration → Lost Reasons</code>. See <a href="./../configuration/lost-reasons.html">Lost reasons</a>.</p><h2 id="mark-an-opportunity-as-won" tabindex="-1">Mark an opportunity as won <a class="header-anchor" href="#mark-an-opportunity-as-won" aria-label="Permalink to &quot;Mark an opportunity as won&quot;">​</a></h2><p>Sharma Textiles accepts the offer for <strong>Annual ERP licence - Sharma Textiles</strong>.</p><ol><li>Open the opportunity from <code>CRM → Sales → My Pipeline</code>.</li><li>Click <strong>Won</strong>.</li></ol>',11)),a(e,{src:"/images1/crm/opportunity-mark-won.png",alt:"Mark as won dialog with the Cancel and Confirm buttons"}),t[1]||(t[1]=o('<ol start="3"><li>Read the dialog <strong>Mark as won</strong>. It says the opportunity moves to the won stage with a probability of 100%.</li><li>Confirm. A notification <strong>Opportunity won</strong> appears.</li></ol><p>The card now sits in the won column with a <strong>Won</strong> label. It shows under the <strong>Won</strong> tab.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The <strong>Won</strong> button is hidden on a deal that is already won, on a lost deal, and on a lead. Convert a lead first.</p></div><h2 id="mark-an-opportunity-as-lost" tabindex="-1">Mark an opportunity as lost <a class="header-anchor" href="#mark-an-opportunity-as-lost" aria-label="Permalink to &quot;Mark an opportunity as lost&quot;">​</a></h2><p>Say another deal, with another customer, falls through because the price is too high.</p><ol><li>Open the opportunity.</li><li>Click <strong>Lost</strong>.</li></ol>',6)),a(e,{src:"/images1/crm/opportunity-mark-lost.png",alt:"Mark as lost dialog with the Lost Reason Too expensive and a Closing Note filled in"}),t[2]||(t[2]=o('<ol start="3"><li>Fill in the dialog <strong>Mark as lost</strong>.</li></ol><ul><li><strong><em>Lost Reason:</em></strong> Why you lost. Optional. Search the list, for example <strong>Too expensive</strong>.</li><li><strong><em>Closing Note:</em></strong> A short note for your team. Optional.</li></ul><p><strong>Example:</strong> Lost Reason <code>Too expensive</code>. Closing Note <code>Competitor offered 12% lower on the annual licence.</code></p><ol start="4"><li>Click <strong>Mark as Lost</strong>. A notification <strong>Opportunity lost</strong> appears.</li></ol><p>The record leaves the board and moves to the <strong>Lost</strong> tab. You can also mark a lead as lost with the <strong>Lost</strong> button on the lead page.</p><h3 id="mark-many-deals-as-lost" tabindex="-1">Mark many deals as lost <a class="header-anchor" href="#mark-many-deals-as-lost" aria-label="Permalink to &quot;Mark many deals as lost&quot;">​</a></h3><ol><li>Open the list layout of <code>CRM → Sales → My Pipeline</code>.</li><li>Select the rows.</li><li>Choose <strong>Mark Lost</strong> from the bulk actions.</li></ol><p>A notification tells you how many records were marked as lost.</p><h2 id="read-a-lost-deal" tabindex="-1">Read a lost deal <a class="header-anchor" href="#read-a-lost-deal" aria-label="Permalink to &quot;Read a lost deal&quot;">​</a></h2><p>Open a lost opportunity from the <strong>Lost</strong> tab. A <strong>Lost</strong> section shows the <strong>Lost Reason</strong> and the <strong>Closing Note</strong>. The <strong>Sales</strong> section shows <strong>Closed At</strong>.</p><h2 id="restore-a-lost-deal" tabindex="-1">Restore a lost deal <a class="header-anchor" href="#restore-a-lost-deal" aria-label="Permalink to &quot;Restore a lost deal&quot;">​</a></h2><p>A lost deal can come back.</p><ol><li>Open the <strong>Lost</strong> tab and select the opportunity.</li><li>Click <strong>Restore</strong>.</li></ol><p>The opportunity returns to the pipeline. A notification <strong>Opportunity restored</strong> appears. The lost reason, closing note and closed date are cleared. Probability goes back to <strong>Automatic</strong>.</p><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Where</th><th>Result</th></tr></thead><tbody><tr><td><strong>Won</strong></td><td>Open deals</td><td>Stage becomes the won stage. Probability becomes 100%.</td></tr><tr><td><strong>Lost</strong></td><td>Open and won deals</td><td>The deal moves to the <strong>Lost</strong> tab. Probability becomes 0%.</td></tr><tr><td><strong>Restore</strong></td><td>Lost deals</td><td>The deal returns to the pipeline as open.</td></tr><tr><td><strong>Force delete</strong></td><td>Lost deals</td><td>The deal is removed for good.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>Force delete</strong> cannot be undone. Use <strong>Restore</strong> if you only want the deal back.</p></div><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><ul><li><strong>Stage.</strong> <strong>Won</strong> moves the deal to the first won stage in the stage order.</li><li><strong>Probability.</strong> Won sets 100%. Lost sets 0%.</li><li><strong>Closed date.</strong> Both actions store <strong>Closed At</strong> with today&#39;s date.</li><li><strong>Moving out of won.</strong> Dragging a won card to an open stage clears <strong>Closed At</strong> and returns the probability to <strong>Automatic</strong>.</li><li><strong>Reports.</strong> Won and lost deals feed the pipeline and lead scoring. See <a href="./../reporting/">CRM reports</a>.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Fill in <strong>Closing Note</strong> every time. A clear note helps the team improve its offers.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./manage-opportunities.html">Manage opportunities</a></li><li><a href="./../configuration/lost-reasons.html">Lost reasons</a></li><li><a href="./../configuration/stages.html">Stages</a></li><li><a href="./../reporting/">CRM reports</a></li></ul>',22))])}const y=s(i,[["render",d]]);export{b as __pageData,y as default};
